using Godot;
using System;
using Settings=Godot.Collections.Dictionary;
public partial class BasicActorOperations
{
    private readonly ActorImageGeneratorOperations _images=new();private readonly ActorAnimationOperations _animation=new();private readonly ActorDataOperations _data=new();
    public string godot_resource_path(string path){if(path.Length==0||path.StartsWith("res://",StringComparison.Ordinal)||path.StartsWith("user://",StringComparison.Ordinal))return path;string root=ProjectSettings.GlobalizePath("res://").Replace('\\','/').TrimEnd('/'),normalized=path.Replace('\\','/');return normalized.StartsWith(root+"/",StringComparison.Ordinal)?"res://"+normalized[(root.Length+1)..]:path;}
    public Resource? load_object_resource(string path){if(path.Length==0||!Godot.FileAccess.FileExists(path))return null;var data=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore);return ActorDataOperations.ScriptIs(data,"res://scripts/actors/core/actor_object_data.gd")?data:null;}
    public string resource_identity(Variant value)=>value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Resource resource?"embedded:"+resource.GetInstanceId():value.ToString();
    public Texture2D? load_external_texture(string path){if(path.Length==0||!Godot.FileAccess.FileExists(path))return null;var image=Image.LoadFromFile(path);return image!=null&&!image.IsEmpty()?ImageTexture.CreateFromImage(image):null;}
    public Texture2D? texture_for_path(Node3D owner,string path){if(path.Length==0)return null;var cache=owner.Get("texture_cache").AsGodotDictionary();if(cache.TryGetValue(path,out var cached))return cached.As<Texture2D>();var texture=load_external_texture(path);cache[path]=texture!=null?Variant.From(texture):default;return texture;}
    public Texture2D? texture_for_value(Node3D owner,Variant value)
    {
        if(value.VariantType==Variant.Type.Object){var obj=value.AsGodotObject();if(obj is Resource reference&&ActorDataOperations.ScriptIs(reference,"res://scripts/actors/core/actor_object_reference.gd")){var data=Resolve(owner,value);if(data==null)return null;if(data.Get("type_id").AsString()=="noise_image"){var cache=owner.Get("noise_texture_cache").AsGodotDictionary();string key=GD.VarToStr(data.Get("values"));if(!cache.ContainsKey(key)){cache.Clear();var texture=_images.texture_for_object(data);cache[key]=texture!=null?Variant.From(texture):default;}return cache[key].As<Texture2D>();}return _images.texture_for_object(data);}if(obj is Resource resource&&ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_data.gd"))return _images.texture_for_object(resource);if(obj is Texture2D texture2D)return texture2D;if(obj is Image image)return ImageTexture.CreateFromImage(image);}if(value.VariantType==Variant.Type.String&&value.AsString().GetExtension().ToLowerInvariant() is "tres" or "res"){var loaded=ResourceLoader.Load(godot_resource_path(value.AsString()));if(ActorDataOperations.ScriptIs(loaded,"res://scripts/actors/core/actor_object_data.gd"))return _images.texture_for_object(loaded);if(loaded is Texture2D texture)return texture;}return texture_for_path(owner,value.ToString());
    }
    public void refresh_saved_image(Node3D owner,Variant source){if(source.VariantType==Variant.Type.String)owner.Get("texture_cache").AsGodotDictionary().Clear();}
    public void watch_shader(Node3D owner,Shader? source){var previous=owner.Get("_watched_shader").As<Shader>();if(previous==source)return;var callback=new Callable(owner,"_source_shader_changed");if(previous!=null&&previous.IsConnected(Resource.SignalName.Changed,callback))previous.Disconnect(Resource.SignalName.Changed,callback);owner.Set("_watched_shader",source!=null?Variant.From(source):default);if(source!=null&&!source.IsConnected(Resource.SignalName.Changed,callback))source.Connect(Resource.SignalName.Changed,callback);}
    public void source_shader_changed(Node3D owner){owner.Set("loaded_shader_path","");owner.CallDeferred("_reload_actor_shader");}
    public Resource? current_material_object(Node3D owner){var actor=owner.Get("actor").As<Resource>();if(actor==null||actor.Get("type_id").AsString() is not ("image_3d" or "basic_shape" or "basic_mesh"))return null;return Resolve(owner,_data.get_value(actor,new StringName("material"),default));}
    public void reload_actor_shader(Node3D owner){if(!owner.IsInsideTree())return;var data=current_material_object(owner);if(data!=null&&data.Get("type_id").AsString()=="shader_material")apply_shader_material(owner,data);}
    public void refresh_saved_shader(Node3D owner,Variant source){var data=current_material_object(owner);var actor=owner.Get("actor").As<Resource>();if(data!=null&&data.Get("type_id").AsString()=="shader_material"){owner.Set("loaded_shader_path","");apply_shader_material(owner,data);}else if(actor!=null&&actor.Get("type_id").AsString()=="camera_3d"){owner.Set("camera_shader_key","");apply_camera_shader(owner,_data.get_value(actor,new StringName("material"),default));}else if(actor!=null&&actor.Get("type_id").AsString()=="fog_volume"){owner.Set("fog_shader_key","");apply_fog(owner,_animation.sampled_values(actor,actor.Get("animation_time").AsDouble()));}}
    public void apply_shader_material(Node3D owner,Resource data)
    {
        var source=Get(data.Get("values").AsGodotDictionary(),"shader_path","");string path=resource_identity(source),key=path;Shader? shader=source.VariantType==Variant.Type.Object?source.AsGodotObject() as Shader:null;if(shader!=null)key+=":"+GD.Hash(shader.Code);else if(source.VariantType==Variant.Type.String&&Godot.FileAccess.FileExists(path))key+=":"+Godot.FileAccess.GetSha256(path);var material=owner.Get("shader_material").As<ShaderMaterial>();if(material==null||key!=owner.Get("loaded_shader_path").AsString()){if(source.VariantType==Variant.Type.String&&path.Length>0)shader=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore) as Shader;watch_shader(owner,shader);owner.Set("loaded_shader_path",key);material=new ShaderMaterial();owner.Set("shader_material",material);if(shader!=null){var timed=_shaderTime.prepare(shader.Code);material.Shader=new Shader{Code=timed["code"].AsString()};material.SetMeta("kiwi_time_uniform",timed["uniform"]);}}assign_material_override(owner,material);apply_shader_uniforms(owner,material,data);
    }
    public ShaderMaterial create_shader_material(Node3D owner,Resource data){var result=new ShaderMaterial();var shader=shader_from_value(owner,Get(data.Get("values").AsGodotDictionary(),"shader_path",""));if(shader==null)return result;var timed=_shaderTime.prepare(shader.Code);result.Shader=new Shader{Code=timed["code"].AsString()};result.SetMeta("kiwi_time_uniform",timed["uniform"]);apply_shader_uniforms(owner,result,data);return result;}
}
